import React,{useEffect,useState} from 'react';
import {Trash2,Download,Activity} from 'lucide-react';
import type {HostAdapter} from '../host/adapter';
import {Empty,IconButton} from '../ui/common';
export default function Trace({host,trace}:{host:HostAdapter,trace:any}){
 const [,tick]=useState(0),[id,setId]=useState(''),[tab,setTab]=useState('messages');
 useEffect(()=>{const timer=setInterval(()=>tick(v=>v+1),750);return()=>clearInterval(timer);},[]);
 const records=[...trace.records].reverse(),record=records.find(x=>x.id===id)??records[0];
 return <div className="wb-trace"><div className="wb-section-title"><Activity size={18}/><strong>生成 Trace</strong><span className="wb-grow"/><IconButton title="清空记录" onClick={()=>{trace.clear();tick(v=>v+1);}}><Trash2 size={16}/></IconButton></div><div className="wb-note">浏览器 → SillyTavern · 最近 20 条，仅本次会话内存记录。响应耗时为收到响应头的时间。</div>{!record?<Empty>发送消息后，可查看请求与世界书命中。</Empty>:<><select aria-label="选择请求记录" value={record.id} onChange={e=>setId(e.target.value)}>{records.map((r,i)=><option key={r.id} value={r.id}>{records.length-i} · {r.generation?.type||'生成'} · HTTP {r.status}</option>)}</select><div className="wb-trace-stats"><span>{record.body?.messages?.length??'—'}<small>消息</small></span><span>{Array.isArray(record.worldInfo)?record.worldInfo.length:'—'}<small>命中条目</small></span><span>{Math.round(record.elapsedMs??0)} ms<small>到响应头</small></span></div><div className="wb-tabs">{[['messages','实际请求'],['world','世界书'],['assembled','组装快照']].map(([v,label])=><button key={v} className={tab===v?'is-active':''} onClick={()=>setTab(v)}>{label}</button>)}</div><div className="wb-trace-body">{tab==='world'?<>{record.worldInfoEvidence!=='WORLD_INFO_ACTIVATED'&&<Empty>未观察到命中事件；不等同于没有命中。</Empty>}{Array.isArray(record.worldInfo)?record.worldInfo.map((e:any,i:number)=><details key={i} open><summary>{e.world??'世界书'} / {e.comment||e.uid}</summary><pre>{e.content}</pre></details>):<pre>{JSON.stringify(record.worldInfo,null,2)}</pre>}</>:tab==='messages'?<>{record.body?.messages?.map((m:any,i:number)=><details key={i} open={i===0}><summary>{i+1} · {m.role}</summary><pre>{typeof m.content==='string'?m.content:JSON.stringify(m.content,null,2)}</pre></details>)}<details><summary>完整请求与参数</summary><pre>{JSON.stringify(record.body,null,2)}</pre></details></>:<><p className="wb-caption">{record.assemblyEvent} · 后续插件可能继续修改</p><pre>{JSON.stringify(record.assembled,null,2)}</pre></>}</div><button onClick={()=>host.download(new Blob([JSON.stringify(record,null,2)],{type:'application/json'}),`trace-${record.id}.json`)}><Download size={15}/>导出此条记录</button></>}</div>;
}
